	def get_xhs_visual_analyst() -> Agent:

	    """每次调用创建一个新的视觉分析 Agent 实例。"""

	    cfg_visual = _agent_cfg("xhs_visual_analyst") # 从 agents.yaml 读取人设

	    return Agent(

	        config=cfg_visual,

	        multimodal=True, # 开启多模态能力

	        llm=get_llm(image_model="qwen3-vl-plus", model="qwen3-max-2026-01-23"),

	        tools=[AddImageToolLocal()], # 赋予查图工具

	    )



	def get_xhs_content_writer() -> Agent:

	    """文本撰写 Agent 实例。"""

	    cfg_writer = _agent_cfg("xhs_content_writer")

	    return Agent(

	        config=cfg_writer,

	        tools=_INTERMEDIATE_TOOLS,

	        llm=get_llm(model="qwen3-max-2026-01-23"), # 纯文本高智商模型

	    )
